import{_ as r,C as i,o as a,c as n,j as t,a as c,E as s,a6 as d}from"./chunks/framework.CD0vXS2f.js";const b=JSON.parse('{"title":"15 · Verification Matrix & Official Sources","description":"Specification verification register separating Microsoft Learn verified rules from subscription-level empirical checks, plus authoritative source links.","frontmatter":{"title":"15 · Verification Matrix & Official Sources","description":"Specification verification register separating Microsoft Learn verified rules from subscription-level empirical checks, plus authoritative source links."},"headers":[],"relativePath":"playbooks/prompt-caching/sources.md","filePath":"playbooks/prompt-caching/sources.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),l={name:"playbooks/prompt-caching/sources.md"};function p(g,e,u,f,m,h){const o=i("PageBrief");return a(),n("div",null,[e[0]||(e[0]=t("h1",{id:"_15-·-verification-matrix-official-microsoft-sources",tabindex:"-1"},[c("15 · Verification Matrix & Official Microsoft Sources "),t("a",{class:"header-anchor",href:"#_15-·-verification-matrix-official-microsoft-sources","aria-label":'Permalink to "15 · Verification Matrix & Official Microsoft Sources"'},"​")],-1)),s(o,{stepLabel:"VERIFICATION REGISTER · 15",readTime:"3 min read",problem:"Production architecture reviews require clarity on which behaviors are published Microsoft Learn guarantees versus regional checks to run in a target subscription.",takeaway:"Every [M] platform claim in Playbook 01 maps directly to authoritative Microsoft Learn / Azure Pricing URLs (R1–R6), separated from [Validate] probes.",csaUse:"Reference links R1–R6 directly to verify sizing formulas, breakpoint limits, retention rules, and isolation guarantees."}),e[1]||(e[1]=d('<p><em>Last verified against published Microsoft Learn and OpenAI documentation: <strong>2026-11-18 21:21 PST</strong>.</em></p><h2 id="_1-technical-specification-verification-matrix" tabindex="-1">1. Technical Specification Verification Matrix <a class="header-anchor" href="#_1-technical-specification-verification-matrix" aria-label="Permalink to &quot;1. Technical Specification Verification Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Technical Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Authoritative Detail / Verification Note</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Minimum prefix, 128-token rounding &amp; <code>5.5</code> retention default</strong></td><td style="text-align:left;"><span class="ev-badge ev-m">[M] Verified in Learn</span></td><td style="text-align:left;">Minimum prefix is <strong>1,024 tokens</strong>. The 128-token rounding on <code>&lt;=5.5</code> <strong>does not apply to GPT-5.6+</strong>. Extended <code>24h</code> retention is default on <code>gpt-5.5</code> (<code>in_memory</code> on <code>&lt;=5.4</code>); <code>5.6+</code> uses <code>ttl</code> (<code>30m</code> default, <code>12h</code> on Responses).</td></tr><tr><td style="text-align:left;"><strong>Maximum explicit breakpoints, read/write limits &amp; pre-5.6 HTTP <code>400</code></strong></td><td style="text-align:left;"><span class="ev-badge ev-m">[M] Verified in Learn</span></td><td style="text-align:left;">Up to <strong>4 new cache writes</strong>/request (3 explicit in <code>implicit</code> mode; 4 in <code>explicit</code> mode) and <strong>50 read breakpoints</strong>. Pre-5.6 models return HTTP <code>400</code> if sent <code>prompt_cache_options</code> or <code>prompt_cache_breakpoint</code>.</td></tr><tr><td style="text-align:left;"><strong>Breakpoint support on PTU-M &amp; <code>272K</code> long-context boundary</strong></td><td style="text-align:left;"><span class="ev-badge ev-m">[M] Verified in Learn</span></td><td style="text-align:left;">GPT-5.6 PTU-M supports automatic prefix caching + <code>prompt_cache_key</code>, <strong>not breakpoints</strong>. GPT-6 and GPT-6.1 support breakpoints on PTU-M; long-context normalized weights (<code>2.0x</code> input, <code>0.2x</code>/<code>0.1x</code> read, <code>2.5x</code> write, <code>7.5x</code> output) apply above <strong>272K input tokens</strong>.</td></tr><tr><td style="text-align:left;"><strong>Structured output schemas (<code>response_format</code>) &amp; <code>reasoning.context</code></strong></td><td style="text-align:left;"><span class="ev-badge ev-m">[M] Verified in Learn</span></td><td style="text-align:left;"><code>response_format</code> is prepended to the system message. <strong><code>gpt-5.6</code> and <code>gpt-6</code> default <code>reasoning.context</code> to <code>all_turns</code></strong> (was <code>current_turn</code> on <code>5.4</code>/<code>5.5</code>), increasing multi-turn tokens unless set to <code>current_turn</code>.</td></tr><tr><td style="text-align:left;"><strong>Responses API vs. Chat Completions API &amp; Nov 1, 2026 write billing</strong></td><td style="text-align:left;"><span class="ev-badge ev-m">[M] Verified in Learn</span></td><td style="text-align:left;">Both APIs support <code>prompt_cache_key</code>, <code>prompt_cache_options</code>, and <code>prompt_cache_breakpoint</code> on 5.6+; <code>12h</code> TTL is supported on Responses API and <code>12h</code> cache-write billing took effect <strong>November 1, 2026</strong>.</td></tr><tr><td style="text-align:left;"><strong>Endpoint cache-hit verification &amp; burst Standard TPM behavior</strong></td><td style="text-align:left;"><span class="ev-badge ev-val">[Validate in Sub]</span></td><td style="text-align:left;">Run the 2-pass cache probe (<a href="./validate/11-seven-layer-gates">Chapter 11</a>) on every target deployment/endpoint (<code>sol</code>, <code>terra</code>, <code>luna</code>) and benchmark burst TPM throttling behavior on Standard spillover legs.</td></tr><tr><td style="text-align:left;"><strong>Regional PTU-M vs. Standard availability &amp; Regional PTU minimums</strong></td><td style="text-align:left;"><span class="ev-badge ev-val">[Validate in Sub]</span></td><td style="text-align:left;">Verify regional availability and minimum PTUs in your target Azure region via Foundry Quota calculator (Global/DZ min is <code>15</code>; Regional <code>5.6-sol/terra</code> lists <code>15</code> in R3 vs. <code>50</code> on R2).</td></tr></tbody></table><h2 id="_2-authoritative-microsoft-openai-reference-register" tabindex="-1">2. Authoritative Microsoft &amp; OpenAI Reference Register <a class="header-anchor" href="#_2-authoritative-microsoft-openai-reference-register" aria-label="Permalink to &quot;2. Authoritative Microsoft &amp; OpenAI Reference Register&quot;">​</a></h2><ul><li><strong>R1 · Prompt caching in Azure OpenAI (<code>[M]</code>):</strong> <a href="https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/prompt-caching" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/prompt-caching</a><br> Specification for <code>prompt_cache_key</code> (<code>~15 RPM</code> sharding), <code>prompt_cache_options</code> (<code>implicit</code>/<code>explicit</code>, <code>ttl: 30m|12h</code>), <code>prompt_cache_breakpoint</code> (4 writes / 50 reads), HTTP <code>400</code> on pre-5.6, and PTU-M rules.</li><li><strong>R2 · Azure OpenAI Service pricing (<code>[M]</code>):</strong> <a href="https://azure.microsoft.com/en-us/pricing/details/cognitive-services/openai-service/" target="_blank" rel="noreferrer">https://azure.microsoft.com/en-us/pricing/details/cognitive-services/openai-service/</a><br> Standard discounted cached-input rates, short (<code>&lt;=272K</code>) vs. long (<code>&gt;272K</code>) context tiers, Provisioned minimum PTU table, and TTL cache-write charges (<code>12h</code> write billing effective Nov 1, 2026).</li><li><strong>R3 · Determine PTU sizing for a workload (<code>[M]</code>):</strong> <a href="https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/provisioned-throughput-sizing" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/provisioned-throughput-sizing</a><br> Per-model Input TPM per PTU and min/increment tables for <code>gpt-5.6-luna/terra/sol</code> (<code>15|15</code> min, <code>5|5</code> increment), <code>gpt-6-astra/sol/luna</code>, and <code>gpt-6.1-sol</code>; 100% cache deduction vs. normalized token weights.</li><li><strong>R4 · Foundry Models region &amp; provisioned availability (<code>[M]</code>):</strong> <a href="https://learn.microsoft.com/en-us/azure/foundry/foundry-models/concepts/models-sold-directly-by-azure-region-availability?pivots=provisioned" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/foundry/foundry-models/concepts/models-sold-directly-by-azure-region-availability?pivots=provisioned</a><br> Regional availability matrix for Global Provisioned, Data Zone Provisioned, and Regional Provisioned (PTU-M) deployments.</li><li><strong>R5 · Azure OpenAI reasoning models (<code>[M]</code>):</strong> <a href="https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/reasoning#preserve-reasoning-across-calls" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/foundry/openai/how-to/reasoning#preserve-reasoning-across-calls</a><br> Documents <code>reasoning.context</code> (<code>all_turns</code> default on <code>gpt-5.6</code> and <code>gpt-6</code> vs. <code>current_turn</code> on <code>5.4</code>/<code>5.5</code>) and Responses API requirement for combining tools with active reasoning on <code>gpt-5.6</code>; see also <a href="https://learn.microsoft.com/en-us/answers/questions/5942997/gpt-5-6-implicit-prompt-caching-and-explicit-promp" target="_blank" rel="noreferrer">Microsoft Q&amp;A #5942997</a>.</li><li><strong>R6 · Use a gateway in front of multiple model deployments (<code>[M]</code>):</strong> <a href="https://learn.microsoft.com/en-us/azure/architecture/ai-ml/guide/azure-openai-gateway-multi-backend" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/architecture/ai-ml/guide/azure-openai-gateway-multi-backend</a><br> Azure Architecture Center reference pattern for Azure API Management PTU-to-Standard spillover, token rate limiting, and OpenTelemetry / Application Insights <code>gen_ai.*</code> telemetry.</li></ul>',5))])}const y=r(l,[["render",p]]);export{b as __pageData,y as default};
